/**
 * 컬렉션 설정 도큐먼트.
 *
 * 기존 ES `.dsearch_collection` 도큐먼트를 MongoDB로 이전.
 * - A/B 인덱스 상태(health, docsCount 등)는 ES 실시간 조회이므로 저장하지 않음
 * - launcher 설정은 YAML 문자열 그대로 저장 (구조가 자유롭고 인덱서에 그대로 전달됨)
 */
@Document(collection = "collections")
@CompoundIndex(def = "{'clusterId': 1, 'baseId': 1}", unique = true)
data class Collection(
    @Id
    val id: String = ObjectId.get().toHexString(),
    @Indexed
    val clusterId: String,
    var name: String,
    var baseId: String,
    var scheduled: Boolean = false,
    var jdbcId: String? = null,
    var cron: String? = null,
    var sourceName: String? = null,
    var autoRun: Boolean = false,
    var replicas: Int? = null,
    var refreshInterval: Int? = null,
    var ignoreRoleYn: String? = null,
    var indexingType: String? = null,
    var extIndexer: Boolean = false,
    // 외부 인덱서 ES 접속 정보 (extIndexer=true 시 사용)
    var esScheme: String? = null,
    var esHost: String? = null,
    var esPort: String? = null,
    var esUser: String? = null,
    var esPassword: String? = null,
    // 외부 인덱서 런처 설정 (YAML 문자열)
    var launcherYaml: String? = null,
    // 런처 접속 정보
    var launcherScheme: String? = null,
    var launcherHost: String? = null,
    var launcherPort: String? = null,
)

