/**
 * 컬렉션 크론 스케줄 관리.
 *
 * - 키: "{clusterId}-{collectionId}-{cron}"
 * - 복수 크론: "||" 구분자로 여러 스케줄 등록 가능
 * - 5자리 cron → Spring 6자리 cron 변환 ("0 " + cron)
 */
@Component
class IndexingScheduler(
    private val taskScheduler: TaskScheduler,
) {
    private val logger = LoggerFactory.getLogger(IndexingScheduler::class.java)
    private val schedules = ConcurrentHashMap<String, ScheduledFuture<*>>()

    fun register(
        clusterId: String,
        collectionId: String,
        cron: String,
        action: () -> Unit,
    ) {
        val cronExpressions = cron.split("||").map { it.trim() }.filter { it.isNotBlank() }
        cronExpressions.forEach { cronExpr ->
            val key = scheduleKey(clusterId, collectionId, cronExpr)
            if (schedules.containsKey(key)) {
                logger.debug("스케줄 이미 등록됨: {}", key)
                return@forEach
            }
            runCatching {
                val springCron = toSpringCron(cronExpr)
                val future =
                    taskScheduler.schedule(
                        { action() },
                        CronTrigger(springCron),
                    )
                schedules[key] = future!!
                logger.info("스케줄 등록: {} ({})", key, springCron)
            }.onFailure { e ->
                logger.error("스케줄 등록 실패 [{}]: {}", key, e.message)
            }
        }
    }

    fun unregister(
        clusterId: String,
        collectionId: String,
    ) {
        val prefix = "$clusterId-$collectionId-"
        schedules.keys
            .filter { it.startsWith(prefix) }
            .forEach { key ->
                schedules.remove(key)?.cancel(false)
                logger.info("스케줄 해제: {}", key)
            }
    }

    fun registeredKeys(): Set<String> = schedules.keys.toSet()

    private fun scheduleKey(
        clusterId: String,
        collectionId: String,
        cron: String,
    ) = "$clusterId-$collectionId-$cron"

    /**
     * 5자리 표준 cron → Spring 6자리 cron.
     * 이미 6자리인 경우 그대로 반환.
     */
    private fun toSpringCron(cron: String): String {
        val parts = cron.trim().split("\\s+".toRegex())
        return if (parts.size == 5) "0 $cron" else cron
    }
}

